function getCarbonBlackTranslation(key, lang) {
    return (carbonblackTranslations[lang] && carbonblackTranslations[lang][key]) ||
           (carbonblackTranslations.en && carbonblackTranslations.en[key]) || null;
}

function applyCarbonBlackTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.carbon-black.") || key.startsWith("review.common."))) {
            const translation = getCarbonBlackTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    
}

window.addEventListener("languageChanged", e => setTimeout(() => applyCarbonBlackTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyCarbonBlackTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyCarbonBlackTranslations(window.i18n?.getCurrentLanguage() || "en");
}
